        self.root = None

    def rotate_left(self, v):

        u = v.rch

        v.rch = u.lch

        u.lch = v

        if u.bias == -1:

            u.bias = v.bias = 0

        else:

            u.bias = 1

            v.bias = -1

        return u

    def rotate_right(self, v):
        u = v.lch

        v.lch = u.rch
        u.rch = v
        if u.bias == 1:

            u.bias = v.bias = 0

        else:

            u.bias = -1

            v.bias = 1

        return u

    def rotateLR(self, v):

        u = v.lch
        t = u.rch

        u.rch = t.lch
        t.lch = u
        v.lch = t.rch

        t.rch = v

        self.update_bias_double(t)

        return t

    def rotateRL(self, v):

        u = v.rch

        t = u.lch

        u.lch = t.rch

        t.rch = u

        v.rch = t.lch

        t.lch = v

        self.update_bias_double(t)

        return t

